mapper.select:
select from finance_receivable_collection c left join sys_dept d on c.dept_id = d.dept_id
c.del_flag = '0' and c.dept_id = #{deptId}
and c.dept_id in
#{deptId}
order by c.priority_level desc, c.age_days desc, c.unpaid_amount desc

select 
from finance_receivable_collection c
left join sys_dept d on c.dept_id = d.dept_id

    c.del_flag = '0'
    and c.dept_id = #{deptId}

        and c.dept_id in

            #{deptId}


    and c.collection_status = #{collectionStatus}
    and c.age_bucket = #{ageBucket}
    and c.priority_level = #{priorityLevel}

        and (c.sale_no like concat('%', #{keyword}, '%') or c.customer_name like concat('%', #{keyword}, '%'))


order by c.next_follow_time is null, c.next_follow_time asc, c.age_days desc

select null as collection_id, r.sale_id, r.sale_no, r.dept_id, d.dept_name, r.member_id, coalesce(r.member_name, r.member_no, r.sale_no) as customer_name, r.sale_amount, coalesce(r.paid_amount, 0) as paid_amount, r.sale_amount - coalesce(r.paid_amount, 0) as unpaid_amount, datediff(curdate(), date(r.sale_date)) as age_days, case when datediff(curdate(), date(r.sale_date)) <= 7 then 'AGE_0_7' when datediff(curdate(), date(r.sale_date)) <= 14 then 'AGE_8_14' when datediff(curdate(), date(r.sale_date)) <= 30 then 'AGE_15_30' else 'AGE_30_PLUS' end as age_bucket, 'PENDING' as collection_status, case when datediff(curdate(), date(r.sale_date)) > 30 or (r.sale_amount - coalesce(r.paid_amount, 0)) >= 5000 then 'CRITICAL' when datediff(curdate(), date(r.sale_date)) > 14 or (r.sale_amount - coalesce(r.paid_amount, 0)) >= 2000 then 'HIGH' when datediff(curdate(), date(r.sale_date)) > 7 or (r.sale_amount - coalesce(r.paid_amount, 0)) >= 500 then 'MEDIUM' else 'LOW' end as priority_level, null as owner_id, null as owner_name, null as promised_pay_date, null as promised_amount, null as next_follow_time, null as last_follow_time, 0 as follow_count from fin_sale_record r left join sys_dept d on r.dept_id = d.dept_id
r.del_flag = '0' and r.sale_amount > coalesce(r.paid_amount, 0) and r.dept_id = #{deptId}
and r.dept_id in
#{deptId}
and datediff(curdate(), date(r.sale_date)) >= #{minAgeDays}
order by age_days desc, unpaid_amount desc

mapper.update:
update finance_receivable_collection
collection_status = #{collectionStatus}, promised_pay_date = #{promisedPayDate}, promised_amount = #{promisedAmount}, next_follow_time = #{nextFollowTime}, last_follow_time = #{lastFollowTime}, follow_count = #{followCount}, update_by = #{updateBy}, update_time = #{updateTime},
where collection_id = #{collectionId}
